import { deploymentPlanSchema } from "../../../src/server/deployment-types";

export const queuePlan = () =>
  deploymentPlanSchema.parse({
    summary:
      "A web application and worker sharing one image with a private queue",
    dockerfile: "Dockerfile",
    generatedDockerfile: null,
    context: ".",
    port: 8080,
    command: ["python", "app.py", "web"],
    environment: [{ name: "QUEUE_HOST", value: "queue" }],
    postgres: null,
    missingInputs: [
      { name: "QUEUE_PASSWORD", reason: "Private broker authentication" },
    ],
    inputBindings: ["app", "worker", "queue"].map((service) => ({
      service,
      variable: "QUEUE_PASSWORD",
      input: "QUEUE_PASSWORD",
    })),
    dependencies: ["app", "worker"].map((service) => ({
      service,
      needs: "queue",
      condition: "healthy",
    })),
    healthPath: "/health",
    services: [
      {
        name: "worker",
        role: "worker",
        imageFrom: "app",
        command: ["python", "app.py", "worker"],
        environment: [{ name: "QUEUE_HOST", value: "queue" }],
        volumes: [],
        configs: [],
        port: null,
        healthPath: null,
        checks: [],
        healthCommand: ["python", "app.py", "ready"],
      },
      {
        name: "queue",
        role: "broker",
        image: "valkey/valkey:8.1.3-alpine",
        command: [
          "sh",
          "-c",
          'exec valkey-server --requirepass "$QUEUE_PASSWORD" --appendonly yes',
        ],
        environment: [],
        volumes: [
          {
            name: "queue-data",
            target: "/data",
            kind: "database",
            sqlite: null,
          },
        ],
        configs: [],
        port: null,
        healthPath: null,
        checks: [],
        healthCommand: [
          "sh",
          "-c",
          'REDISCLI_AUTH="$QUEUE_PASSWORD" valkey-cli ping | grep -qx PONG',
        ],
      },
    ],
    checks: [
      {
        name: "Home content",
        method: "GET",
        path: "/",
        body: null,
        expectedStatus: 200,
        contains: "Background job fixture",
        captureId: null,
      },
      {
        name: "Submit synthetic job",
        method: "POST",
        path: "/jobs",
        body: { message: "SG_VERIFY_TOKEN" },
        expectedStatus: 201,
        contains: "SG_VERIFY_TOKEN",
        captureId: "id",
      },
      {
        name: "Worker processed the job",
        method: "GET",
        path: "/jobs/{id}",
        body: null,
        expectedStatus: 200,
        contains: "processed:SG_VERIFY_TOKEN",
        captureId: null,
        waitSeconds: 5,
      },
      {
        name: "Remove synthetic job",
        method: "DELETE",
        path: "/jobs/{id}",
        body: null,
        expectedStatus: 200,
        contains: "deleted",
        captureId: null,
      },
    ],
  });
